df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

# Filter to sale rows in USD only
sale_df = df[(df['row_kind'] == 'sale') & (df['Currency'] == 'USD')].copy()

# EDA
try:
    metric_cols = ['Weight', 'Linehaul', 'Fuel Surcharge', 'Accessorials', 'Total Charge']
    for col in metric_cols:
        s = df[col].dropna()
        result['eda_summary'][col] = {
            'mean': float(s.mean()), 'std': float(s.std()),
            'min': float(s.min()), 'max': float(s.max()),
            'median': float(s.median()), 'count': int(s.count())
        }
except Exception:
    pass

# Correlations
try:
    num_df = sale_df[metric_cols].dropna()
    corr_matrix = num_df.corr(method='pearson')
    for i, c1 in enumerate(metric_cols):
        for j, c2 in enumerate(metric_cols):
            if j <= i:
                continue
            r = corr_matrix.loc[c1, c2]
            if abs(r) >= 0.2:
                result['correlations'][f'{c1}__{c2}'] = round(float(r), 4)
except Exception:
    pass

# Segmentation
try:
    seg_cols = ['Carrier', 'Mode', 'Status']
    agg_map = {'Weight': 'sum', 'Linehaul': 'sum', 'Fuel Surcharge': 'sum',
               'Accessorials': 'sum', 'Total Charge': 'sum'}
    for seg in seg_cols:
        for metric in metric_cols:
            grp = sale_df.groupby(seg)[metric].sum().reset_index()
            grp = grp.sort_values(metric, ascending=False).head(10)
            result['segments'].append({
                'segment_column': seg, 'metric_column': metric,
                'aggregation': 'sum', 'label': None,
                'results': [{'name': str(r[seg]), 'value': round(float(r[metric]), 4)} for _, r in grp.iterrows()]
            })
    # On-time delivery rate by Carrier
    ot_df = sale_df.copy()
    on_time_num = ot_df[ot_df['days_before_promise'] >= 0].groupby('Carrier')['Shipment ID'].nunique()
    denom_mask = (
        (ot_df['days_before_promise'] >= 0) |
        (ot_df['days_late'] > 0) |
        (ot_df['Status'].str.lower().isin(['in transit','out for delivery','picked up','exception',
            'delivery exception','delayed','tendered','booked','dispatched','pending','shipped',
            'partially shipped','backordered','short shipped','open','allocated','released',
            'picked','packed']) & (ot_df['days_past_due'] > 0))
    )
    on_time_den = ot_df[denom_mask].groupby('Carrier')['Shipment ID'].nunique()
    ot_rate = (on_time_num / on_time_den).dropna()
    ot_rate = ot_rate.sort_values(ascending=False).head(10)
    result['segments'].append({
        'segment_column': 'Carrier', 'metric_column': 'Shipment ID',
        'aggregation': 'ratio', 'label': 'on_time_delivery_rate',
        'results': [{'name': str(k), 'value': round(float(v), 4)} for k, v in ot_rate.items()]
    })
    # Cost per lb by Carrier
    cpb_df = sale_df[(sale_df['Weight'] > 0) & (sale_df['Weight UOM'].notna())]
    cpb_num = cpb_df.groupby('Carrier')['Total Charge'].sum()
    cpb_den = cpb_df.groupby('Carrier')['Weight'].sum()
    cpb = (cpb_num / cpb_den).dropna().sort_values(ascending=False).head(10)
    result['segments'].append({
        'segment_column': 'Carrier', 'metric_column': 'Total Charge',
        'aggregation': 'ratio', 'label': 'cost_per_lb',
        'results': [{'name': str(k), 'value': round(float(v), 4)} for k, v in cpb.items()]
    })
except Exception:
    pass

# Trends (MoM on Ship Date for target metrics)
try:
    import numpy as np
    trend_df = sale_df.copy()
    trend_df['ship_month'] = pd.to_datetime(trend_df['Ship Date']).dt.to_period('M')
    for metric in metric_cols:
        monthly = trend_df.groupby('ship_month')[metric].sum().sort_index()
        if len(monthly) >= 2:
            pct = float((monthly.iloc[-1] - monthly.iloc[-2]) / monthly.iloc[-2] * 100) if monthly.iloc[-2] != 0 else 0.0
            direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
            result['trends'].append({
                'column': metric, 'period': 'MoM', 'direction': direction,
                'pct_change': round(pct, 4), 'segment': None
            })
    # Transit days trend
    td_df = trend_df[trend_df['transit_days'] >= 0]
    td_monthly = td_df.groupby('ship_month')['transit_days'].mean().sort_index()
    if len(td_monthly) >= 2:
        pct_td = float((td_monthly.iloc[-1] - td_monthly.iloc[-2]) / td_monthly.iloc[-2] * 100) if td_monthly.iloc[-2] != 0 else 0.0
        result['trends'].append({
            'column': 'transit_days', 'period': 'MoM',
            'direction': 'up' if pct_td > 1 else ('down' if pct_td < -1 else 'flat'),
            'pct_change': round(pct_td, 4), 'segment': None
        })
except Exception:
    pass

# Forecasting (simple linear extrapolation of Total Charge MoM)
try:
    import numpy as np
    fc_df = sale_df.copy()
    fc_df['ship_month'] = pd.to_datetime(fc_df['Ship Date']).dt.to_period('M')
    monthly_tc = fc_df.groupby('ship_month')['Total Charge'].sum().sort_index()
    if len(monthly_tc) >= 3:
        x = np.arange(len(monthly_tc))
        y = monthly_tc.values.astype(float)
        coeffs = np.polyfit(x, y, 1)
        next_val = float(np.polyval(coeffs, len(monthly_tc)))
        next_period = str(monthly_tc.index[-1] + 1)
        result['forecast_points'].append({'period': next_period, 'value': round(next_val, 2)})
except Exception:
    pass

# Anomalies
try:
    import numpy as np
    from scipy import stats as sp_stats
    anomaly_cols = ['Weight', 'Linehaul', 'Fuel Surcharge', 'Accessorials', 'Total Charge']
    total_anomalies = 0
    for col in anomaly_cols:
        if total_anomalies >= 25:
            break
        s = sale_df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(sp_stats.skew(s))
        use_log = abs(skew) > 2
        if use_log:
            shift = max(0, -s.min()) + 1
            sv = np.log1p(s + shift)
        else:
            sv = s.copy()
            shift = 0
        q1, q3 = sv.quantile(0.25), sv.quantile(0.75)
        iqr = q3 - q1
        lo, hi = q1 - 3 * iqr, q3 + 3 * iqr
        flagged = sv[(sv < lo) | (sv > hi)]
        if len(flagged) / len(sv) > 0.05:
            result['anomalies'].append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'{float(s.quantile(0.25)):.2f}–{float(s.quantile(0.75)):.2f}',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme values are a natural distribution, not flagged individually'
            })
            continue
        if use_log:
            lo_orig = float(np.expm1(lo) - shift)
            hi_orig = float(np.expm1(hi) - shift)
        else:
            lo_orig, hi_orig = float(lo), float(hi)
        exp_range = f'{lo_orig:.2f}–{hi_orig:.2f}'
        for idx in flagged.index:
            if total_anomalies >= 25:
                break
            raw_val = float(s.loc[idx])
            sv_val = float(sv.loc[idx])
            lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
            lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
            if sv_val > hi5 or sv_val < lo5:
                sev = 'critical'
            elif sv_val > hi4 or sv_val < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            result['anomalies'].append({
                'column': col, 'row_index': int(idx), 'value': raw_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {raw_val:.2f} lies outside expected range {exp_range}'
            })
            total_anomalies += 1
except Exception:
    pass

result['assumptions'] = [
    'Only sale rows in USD are used for all KPIs and segmentation; cancelled and non-USD rows excluded.',
