# Anomalies
try:
    import numpy as np
    from scipy import stats as sp_stats
    anomaly_cols = ['Weight', 'Linehaul', 'Fuel Surcharge', 'Accessorials', 'Total Charge']
    total_anomalies = 0
    for col in anomaly_cols:
        if total_anomalies >= 25:
            break
        s = sale_df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(sp_stats.skew(s))
        use_log = abs(skew) > 2
        if use_log:
            shift = max(0, -s.min()) + 1
            sv = np.log1p(s + shift)
        else:
            sv = s.copy()
            shift = 0
        q1, q3 = sv.quantile(0.25), sv.quantile(0.75)
        iqr = q3 - q1
        lo, hi = q1 - 3 * iqr, q3 + 3 * iqr
        flagged = sv[(sv < lo) | (sv > hi)]
        if len(flagged) / len(sv) > 0.05:
            result['anomalies'].append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'{float(s.quantile(0.25)):.2f}–{float(s.quantile(0.75)):.2f}',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme values are a natural distribution, not flagged individually'
            })
            continue
        if use_log:
            lo_orig = float(np.expm1(lo) - shift)
            hi_orig = float(np.expm1(hi) - shift)
        else:
            lo_orig, hi_orig = float(lo), float(hi)
        exp_range = f'{lo_orig:.2f}–{hi_orig:.2f}'
        for idx in flagged.index:
            if total_anomalies >= 25:
                break
            raw_val = float(s.loc[idx])
            sv_val = float(sv.loc[idx])
            lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
            lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
            if sv_val > hi5 or sv_val < lo5:
                sev = 'critical'
            elif sv_val > hi4 or sv_val < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            result['anomalies'].append({
                'column': col, 'row_index': int(idx), 'value': raw_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {raw_val:.2f} lies outside expected range {exp_range}'
            })
            total_anomalies += 1
except Exception:
    pass

