        lo4 = q1 - 4 * iqr
        hi4 = q3 + 4 * iqr
        lo5 = q1 - 5 * iqr
        hi5 = q3 + 5 * iqr
        extreme_mask = (s_t < lo3) | (s_t > hi3)
        if extreme_mask.sum() / len(s_t) > 0.05:
            anomalies.append({
