            continue
        skew = float(s.skew())
        shift = 0
        if s.min() < 0:
            shift = -s.min() + 1
        s_t = np.log1p(s + shift) if abs(skew) > 2 else s
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo3, hi3 = q1 - 3 * iqr, q3 + 3 * iqr
        lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
        lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr

        mask = (s_t < lo3) | (s_t > hi3)
        if mask.sum() / len(s) > 0.05:
            anomalies.append({
                "column": col, "row_index": None, "value": None,
                "expected_range": f"{float(s.quantile(0.25)):.2f} to {float(s.quantile(0.75)):.2f}",
                "severity": "low",
                "explanation": f"{col} is heavy-tailed; extreme values are a natural distribution, not flagged individually"
            })
            continue

        flagged = s[mask].index
        if abs(skew) > 2:
            lo_orig = float(np.expm1(lo3) - shift)
            hi_orig = float(np.expm1(hi3) - shift)
        else:
            lo_orig, hi_orig = float(lo3), float(hi3)

        for idx in flagged:
            if len(anomalies) >= cap:
                break
            val = float(s[idx])
            t_val = float(s_t[idx])
            if t_val < lo5 or t_val > hi5:
                sev = "critical"
            elif t_val < lo4 or t_val > hi4:
                sev = "high"
            else:
                sev = "medium"
            anomalies.append({
                "column": col, "row_index": int(idx), "value": val,
                "expected_range": f"{lo_orig:.2f} to {hi_orig:.2f}",
                "severity": sev,
                "explanation": f"{col} value {val:.2f} lies outside expected range {lo_orig:.2f} to {hi_orig:.2f}"
            })

    result['anomalies'] = anomalies
except Exception:
    pass

# --- ASSUMPTIONS ---
result['assumptions'] = [
    "Cancelled rows (row_kind='cancelled') excluded from all KPIs and segmentation.",
    "dwell_hours, hours_before_appointment, hours_late_to_appointment used as pre-computed; not re-derived.",
    "On-time arrival = arrived on or before appointment time (hours_before_appointment >= 0).",
    "Avg dwell computed as sum(dwell_hours) / count(distinct appointments) where dwell_hours >= 0.",
    "Anomaly detection uses 3×IQR boundary; log1p transform applied when |skew| > 2."
]
